```ts
const env = link.connection.env ?? {};
const lines = Object.entries(env).map(([k,v]) => `${k}=${v}`).join('\n');
if (!lines) { ... }
copyText(lines)
```
Add `DATABASE_URL`? The connection.env from mock includes DB_* only. The design says env includes DATABASE_URL if password managed. The daemon's connection.env likely includes it. We use as-is.

`setPassword`:
```ts
async function setPassword(link) {
  settingPassword = {...settingPassword, [link.id]: true};
  try {
    const secret = await setServiceUserPassword(link.service_id, link.user_id);
    secrets = {...secrets, [link.id]: secret.value};
    managed = {...managed, [link.id]: true};
    restartNeeded = true;
    addToast({kind:'success', title:'Password set', message:'Restart the site to apply the new password.'});
    onRefresh();
  } catch (caught) { toastError('Could not set the database password', describeError(caught).message); }
  finally { ... }
}
